#requires -Version 7.4
[CmdletBinding()]
param([switch]$Check,[string]$CatalogDirectory='',[string]$OutputRoot='')
. "$PSScriptRoot/self-service-common.ps1"
$root=if ($OutputRoot) { [IO.Path]::GetFullPath($OutputRoot) } else { Get-ProjectRoot }
if (!$CatalogDirectory) { $CatalogDirectory=Join-Path (Get-ProjectRoot) 'self-service/targets' }
$targets=@(Get-ChildItem $CatalogDirectory -Filter *.json | Sort-Object Name | ForEach-Object { Get-Content $_.FullName -Raw | ConvertFrom-Json -AsHashtable })
if (!$targets.Count) { throw 'No registered target profiles.' }
$selections=@{}; $aliases=@{}
foreach ($t in $targets) {
    if ($t.schemaVersion -ne 2) { throw 'Dropdown generation requires schemaVersion 2 target profiles.' }
    foreach ($key in @('workload','environmentName','subscriptionAlias','networkProfile')) { if ($t[$key] -cnotmatch '^[a-z0-9][a-z0-9-]{0,39}$') { throw "Invalid catalog key: $key" } }
    foreach ($key in @('serviceConnection','agentPool','deploymentEnvironment')) { if ($t[$key] -cnotmatch '^[a-zA-Z0-9][a-zA-Z0-9._-]{0,79}$') { throw "Invalid protected resource binding: $key" } }
    if ($t.subscriptionId -ne [guid]::Empty.ToString()) { Assert-ServiceTarget $t $t.workload $t.environmentName -AllowDisabled }
    elseif ($t.enabled -isnot [bool] -or $t.enabled) { throw 'A placeholder subscription cannot be enabled.' }
    $key="$($t.workload)/$($t.environmentName)/$($t.subscriptionAlias)/$($t.networkProfile)"
    if ($selections.ContainsKey($key)) { throw 'Duplicate subscription/network target selection.' }; $selections[$key]=$true
    if ($aliases.ContainsKey($t.subscriptionAlias) -and $aliases[$t.subscriptionAlias] -ine $t.subscriptionId) { throw 'One subscription alias cannot identify different subscription IDs.' }; $aliases[$t.subscriptionAlias]=$t.subscriptionId
}
$yaml=@('# Generated by scripts/Update-ServiceCatalog.ps1. Review catalog changes before merging.','trigger: none','pr: none','','parameters:',
    '  - name: operation','    displayName: Read-only discovery or deployment','    type: string','    default: discover','    values: [discover, deploy]')
foreach ($pair in @(@('workload','workload','Registered workload'),@('environment','environmentName','Target environment'),@('subscription','subscriptionAlias','Approved subscription'),@('network','networkProfile','Network profile'))) {
    $values=@($targets | ForEach-Object { $_[$pair[1]] } | Sort-Object -Unique)
    $yaml+=@("  - name: $($pair[0])","    displayName: $($pair[2])",'    type: string',"    default: $($values[0])",('    values: ['+($values -join ', ')+']'))
}
$yaml+=@('','variables:','  - template: pipelines/catalog-bindings.yml','    parameters:','      workload: ${{ parameters.workload }}','      environment: ${{ parameters.environment }}','      subscription: ${{ parameters.subscription }}','      network: ${{ parameters.network }}','','stages:')
foreach ($op in @('discover','deploy')) {
    $template=if ($op -eq 'discover') {'self-service-discover'} else {'self-service-stages'}
    $yaml+=@(('  - ${{ if eq(parameters.operation, '''+$op+''') }}:'),"    - template: pipelines/templates/$template.yml",'      parameters:','        workload: ${{ parameters.workload }}','        environment: ${{ parameters.environment }}','        subscription: ${{ parameters.subscription }}','        network: ${{ parameters.network }}')
}
$bindings=@('# Generated compile-time bindings. Never resolve service connections using runtime output variables.','parameters:')
foreach ($key in @('workload','environment','subscription','network')) { $bindings+=@("  - name: $key",'    type: string') }
$bindings+=@('variables:')
$conditions=@()
foreach ($t in $targets) {
    $condition='and(eq(parameters.workload, '''+$t.workload+'''), eq(parameters.environment, '''+$t.environmentName+'''), eq(parameters.subscription, '''+$t.subscriptionAlias+'''), eq(parameters.network, '''+$t.networkProfile+'''))'
    $conditions+=$condition
    $bindings+=@(('  ${{ if '+$condition+' }}:'),"    serviceConnection: $($t.serviceConnection)","    agentPool: $($t.agentPool)","    deploymentEnvironment: $($t.deploymentEnvironment)")
}
$anyMatch=if ($conditions.Count -eq 1) {$conditions[0]} else {'or('+($conditions -join ', ')+')'}
$bindings+=@(('  ${{ if not('+$anyMatch+') }}:'),'    serviceConnection: UNREGISTERED_SELECTION','    agentPool: UNREGISTERED_SELECTION','    deploymentEnvironment: UNREGISTERED_SELECTION')
foreach ($item in @(@('azure-pipelines-self-service.yml',$yaml),@('pipelines/catalog-bindings.yml',$bindings))) {
    $path=Join-Path $root $item[0]; $text=($item[1] -join "`n")+"`n"
    if ($Check) {
        if (!(Test-Path $path) -or ([IO.File]::ReadAllText($path).Replace("`r`n","`n")) -cne $text) { throw "Generated catalog is stale: $($item[0]). Run Update-ServiceCatalog.ps1." }
    } else { New-Item -ItemType Directory -Path (Split-Path -Parent $path) -Force | Out-Null; [IO.File]::WriteAllText($path,$text,[Text.UTF8Encoding]::new($false)) }
}
Write-Host "PASS: catalog has $($targets.Count) unique registered target selections."
